function vAutoScene(sc,text,i,keepMain){
 const p=String(sc||'paper|book').split('|'),t=String(text||'');let bg=p[0];
 const ok=k=>typeof ART==='undefined'||!ART.names||ART.names.includes(k);
 const bgHit=VBGKEYS.find(k=>k[0].test(t));if(bgHit&&(typeof ART==='undefined'||!ART.bgs||ART.bgs.includes(bgHit[1])))bg=bgHit[1];
 const topics=VTOPKEYS.filter(k=>k[0].test(t)).map(k=>k[1]).filter(ok);
 const found=[...topics,...VKEYS.filter(k=>k[0].test(t)).map(k=>k[1]).filter(ok)];
 const main=keepMain&&!topics.length?[p[1]].filter(Boolean):[];
 let items=[...new Set([...main,...found])];
 if(items.length<2)items=[...new Set([...items,...(found.length||keepMain?p.slice(1):[p[1],VFILL[i%VFILL.length]])])];
 return [bg,...items.slice(0,2)].join('|');
}
