 $$('[data-vchap]',$('#vDesc')).forEach(b=>b.onclick=()=>{go(+b.dataset.vchap);$('#vPlayer').scrollIntoView?.({block:'nearest',behavior:'smooth'});vPlay();});
 $('#vMore').onclick=()=>{const d=$('#vDesc');d.classList.toggle('open');$('#vMore').textContent=d.classList.contains('open')?'一部を表示':'もっと見る';};
