 const coach=()=>coachURL(l.sl[V.slide][1].replace(/\//g,' '),l.sl.map(x=>x[1]));$('#vCoach').href=coach();$('#vCoach').onclick=e=>{e.currentTarget.href=coach();};
 vCCLabel();$('#vCC').onclick=()=>{V.cc=VCC[(VCC.indexOf(V.cc)+1)%VCC.length];lsSet('ee-vcc',V.cc);$('#vPlayer').dataset.cc=V.cc;vCCLabel();};
