// ---- Mobile-safe speech (iOS Safari / Android Chrome) ----
// 1) iOS only allows speech that starts inside a tap: speak a silent utterance on the first touch to unlock it.
// 2) cancel() immediately followed by speak() drops the new utterance on many phones: cancel only when busy, then wait a moment.
// 3) "interrupted"/"canceled" errors come from our own cancel() and are not failures.
let vSpeechPrimed=false;
let vLastCancel=0;
stopSpeech=function(){playTok++;try{const ss=speechSynthesis;if(ss.speaking||ss.pending){ss.cancel();vLastCancel=Date.now();}}catch(e){}};
function vPrimeSpeech(){if(vSpeechPrimed||!('speechSynthesis' in window))return;vSpeechPrimed=true;try{const u=new SpeechSynthesisUtterance(' ');u.volume=0;u.lang='en-US';speechSynthesis.speak(u);}catch(e){}if(!voices.length)try{loadVoices();}catch(e){}}
['touchend','pointerup','click','keydown'].forEach(ev=>document.addEventListener(ev,vPrimeSpeech,{capture:true,passive:true}));
const vNav=typeof navigator!=='undefined'?navigator:{userAgent:'',platform:'',maxTouchPoints:0};const vMobileSpeech=/Android|iPhone|iPad|iPod/i.test(vNav.userAgent)||(vNav.platform==='MacIntel'&&vNav.maxTouchPoints>1);
speak=function(text,mul,voice,keep,onb){
 if(!('speechSynthesis' in window)){toast('この端末では英語の読み上げが使えません');return Promise.resolve();}
 if(!keep)playTok++;
 const ss=speechSynthesis;SPEAKERR=null;
 if(!voices.length)try{loadVoices();}catch(e){}
 let busy=ss.speaking||ss.pending;if(busy){try{ss.cancel();}catch(e){}vLastCancel=Date.now();}busy=busy||Date.now()-vLastCancel<150;
 try{if(ss.paused)ss.resume();}catch(e){}
 const role=String(text).match(/^([MF]):\s*/);if(role)text=String(text).slice(role[0].length);
 const u=new SpeechSynthesisUtterance(String(text));let v=voice||(role?voiceFor(role[1]):pickVoice());
 if(v&&!ss.getVoices().some(x=>x.voiceURI===v.voiceURI))v=null; // stale voice objects are ignored silently on some phones
 if(v){u.voice=v;u.lang=v.lang;}else u.lang='en-US';
 const rate=Math.max(0.4,Math.min(1.8,(settings().rate||1)*(mul||1)));u.rate=rate;
 if(onb)u.onboundary=e=>{if(typeof e.charIndex==='number')onb(e.charIndex);};
 return new Promise(res=>{let done=false,started=false;const fin=()=>{if(!done){done=true;res();}};
  u.onstart=()=>{started=true;};u.onend=fin;
  u.onerror=e=>{const er=e&&e.error;if(er&&er!=='interrupted'&&er!=='canceled')SPEAKERR=er;fin();};
  setTimeout(()=>{if(!started&&!done&&vMobileSpeech&&!ss.speaking)SPEAKERR=SPEAKERR||'no-start';fin();},Math.max(3000,String(text).length*120/rate));
  const go=()=>{try{ss.speak(u);}catch(e){SPEAKERR='error';fin();}};
  if(busy&&vMobileSpeech)setTimeout(go,120);else go();});
};
// Settings: show what the device offers, so a silent phone can be diagnosed.
function vSpeechDiag(){const el=$('#vSpeechDiag');if(!el)return;if(!('speechSynthesis' in window)){el.textContent='この端末・ブラウザーは読み上げに対応していません。';return;}const en=speechSynthesis.getVoices().filter(v=>/^en/i.test(v.lang));el.textContent='英語の声：'+en.length+'個'+(en.length?'（'+en.slice(0,3).map(v=>v.name).join('、')+(en.length>3?' ほか':'')+'）':'。端末の設定で英語の音声データを入れると使えます。')+(SPEAKERR?' ／ 直前のエラー：'+SPEAKERR:'');}
{const t=$('#stTest');if(t&&t.insertAdjacentHTML){t.insertAdjacentHTML('afterend','<p class="small muted" id="vSpeechDiag"></p><p class="small muted">音が出ないとき：音量・マナーモード（iPhone は横のスイッチ）を確認し、一度画面をタップしてから再生してください。Android は「設定 → システム → 言語 → 音声出力（テキスト読み上げ）」で英語の音声データを入れてください。</p>');t.addEventListener('click',()=>setTimeout(vSpeechDiag,1500));if('speechSynthesis' in window)speechSynthesis.addEventListener?.('voiceschanged',vSpeechDiag);setTimeout(vSpeechDiag,800);}}
// Opening English Express with ?coach=<url> (the QR code printed by start_coach_phone.bat) saves the coach URL once.
(function(){try{if(typeof location==='undefined'||!location.search)return;const q=new URLSearchParams(location.search);const c=q.get('coach');if(!c)return;const u=new URL(c);const ok=(u.protocol==='https:'&&/(^|\.)(gradio\.live|hf\.space)$/i.test(u.hostname))||/^(127\.0\.0\.1|localhost)$/i.test(u.hostname);if(ok){const v=(u.origin+u.pathname).replace(/\/+$/,'');saveSettings({coach:v});if($('#stCoach'))$('#stCoach').value=v;setTimeout(()=>toast('発音コーチのURLを保存しました（'+u.hostname+'）'),600);}q.delete('coach');history.replaceState(null,'',location.pathname+(q.toString()?'?'+q.toString():'')+location.hash);}catch(e){}})();

// ---- Pronunciation coach: pass the whole lesson so the coach can list it sentence by sentence.
coachURL=function(text,passage){const base=String(settings().coach||'http://127.0.0.1:7860').trim().replace(/\/+$/,'');const t=String(text||'').replace(/\s+/g,' ').trim();const all=(Array.isArray(passage)?passage:[passage]).map(x=>String(x||'').replace(/\//g,' ').replace(/\s+/g,' ').trim()).filter(Boolean).join('\n');const q=[];if(t)q.push('text='+encodeURIComponent(t));if(all&&all!==t)q.push('passage='+encodeURIComponent(all.slice(0,6000)));return base+'/'+(q.length?'?'+q.join('&'):'');};
// Shorts: the speak sheet lets you pick any sentence of the short, not only the one on screen.
const VPROMPT=/^(How would you say this|Listen, then try|Now say it in your own words)/i;
function vShortLines(s){return (s.sl||[]).map((sl,i)=>({i,en:slideText(sl),ja:sl[2]||''})).filter(x=>x.en&&!VPROMPT.test(x.en));}
openSpeakSheet=function(it,pick){
 spStop();const lines=vShortLines(it.s);if(!lines.length)return;const cur=pick!==undefined?pick:(SP.it===it?SP.slide:0);
 const k=Math.max(0,lines.findIndex(x=>x.i===cur));const sent=lines[k].en;const sh=it.el.querySelector('.sheet');
 if(SP.it===it||pick!==undefined){SP.it=it;SP.slide=lines[k].i;showSlide(it,lines[k].i);}
 sh.innerHTML='<div class="row"><b class="jp">発音チェック</b><span class="spacer"></span><button class="btn sm" data-close>閉じる</button></div>'
  +(lines.length>1?'<label class="small jp">文を選ぶ（この動画の'+lines.length+'文）<select class="vpick" data-vpick>'+lines.map((x,j)=>'<option value="'+x.i+'"'+(j===k?' selected':'')+'>'+(j+1)+'. '+esc(x.en.slice(0,70))+'</option>').join('')+'</select></label>':'')
  +'<div class="target">'+esc(sent)+'</div><div class="row"><button class="btn say sm" data-say="'+esc(sent)+'">手本</button><button class="btn say sm" data-say="'+esc(sent)+'" data-rate="0.7">ゆっくり</button></div><div class="row"><a class="btn primary sm" target="_blank" rel="noopener" href="'+esc(coachURL(sent,lines.map(x=>x.en)))+'">音素分析（発音コーチ）</a><span class="tiny muted jp">録音して音素ごとに採点。コーチでもこの動画の文を1文ずつ選べます</span></div><div class="hintbox">簡易チェック：入力欄をタップしてキーボードのマイク（PC は Win + H）で読む。</div><textarea data-sin placeholder="ここに音声入力"></textarea><button class="btn primary" data-sj>判定する</button><div data-sout class="stack"></div>';
 sh.hidden=false;sh.querySelector('[data-close]').onclick=()=>closeSheet(it);
 const sel=sh.querySelector('[data-vpick]');if(sel)sel.onchange=e=>openSpeakSheet(it,+e.target.value);
 sh.querySelector('[data-sj]').onclick=()=>{const r=judgeInto(sh.querySelector('[data-sout]'),sent,sh.querySelector('[data-sin]').value,true);if(r)bump({pron:1});};
};
// Shorts: questions for every short (its own question if any, plus meaning and listening-cloze questions made from its sentences).
// Blanks and wrong choices use lower-case words only, so names and places are not used.
const VSTOP=new Set('about,after,again,also,been,before,being,because,could,does,each,even,every,from,have,here,into,just,like,made,make,many,more,most,much,only,other,over,said,same,some,such,than,that,their,them,then,there,these,they,this,those,very,were,what,when,where,which,while,will,with,would,your'.split(','));
let VQPOOL=null;const VQCACHE=new Map();
function vQPool(){if(VQPOOL)return VQPOOL;const words=new Set(),ja=new Set();shortsAll().forEach(s=>vShortLines(s).forEach(x=>{if(x.ja)ja.add(x.ja);(x.en.match(/[A-Za-z]+/g)||[]).forEach(w=>{if(w===w.toLowerCase()&&w.length>=4&&!VSTOP.has(w))words.add(w);});}));return VQPOOL={words:[...words].sort(),ja:[...ja].sort()};}
function vPickN(pool,n,seed,avoid){const out=[],seen=new Set(avoid.map(x=>String(x).toLowerCase()));for(let k=0;out.length<n&&k<pool.length*3+30;k++){const c=pool[vHash(seed+':'+k)%pool.length];if(c&&!seen.has(String(c).toLowerCase())){seen.add(String(c).toLowerCase());out.push(c);}}return out;}
function vOrder(choices,seed){const idx=choices.map((_,k)=>k).sort((a,b)=>vHash(seed+'#'+a)-vHash(seed+'#'+b));return [idx.map(k=>choices[k]),idx.indexOf(0)];}
function vShortQs(s){
 const key=(s.id||s.t||'')+'|'+(s.sl||[]).length;if(VQCACHE.has(key))return VQCACHE.get(key).map(q=>[q[0],q[1].slice(),q[2]]);
 const qs=[],seed=s.id||s.t||'short',lines=vShortLines(s),pool=vQPool();
 if(s.q&&Array.isArray(s.q[1])&&s.q[1].length>=2)qs.push([String(s.q[0]),s.q[1].map(String),+s.q[2]||0]);
 const withJa=lines.filter(x=>x.ja);
 if(withJa.length){const m=withJa[vHash(seed+'m')%withJa.length];let wrong=vPickN(withJa.filter(x=>x.ja!==m.ja).map(x=>x.ja),3,seed+'mo',[m.ja]);if(wrong.length<3)wrong=wrong.concat(vPickN(pool.ja,3-wrong.length,seed+'mp',[m.ja,...wrong]));if(wrong.length){const [c,a]=vOrder([m.ja,...wrong],seed+'mq');qs.push(['この文の意味は？「'+m.en+'」',c,a]);}}
 const order=lines.map((x,j)=>j).sort((a,b)=>vHash(seed+'c'+a)-vHash(seed+'c'+b));let cloze=0;
 for(const j of order){if(cloze>=2)break;const en=lines[j].en;const cands=[...new Set((en.match(/[A-Za-z]+/g)||[]).filter(w=>w===w.toLowerCase()&&w.length>=4&&!VSTOP.has(w)))];if(!cands.length)continue;
  const w=cands[vHash(seed+'w'+j)%cands.length],lw=w.toLowerCase();const near=pool.words.filter(x=>Math.abs(x.length-lw.length)<=2&&x!==lw);const wrong=vPickN(near.length>=3?near:pool.words,3,seed+'cw'+j,[lw]);if(wrong.length<1)continue;
  const blanked=en.replace(new RegExp('\\b'+w+'\\b'),'＿＿＿');const [c,a]=vOrder([lw,...wrong],seed+'cq'+j);qs.push(['聞き取り：空所に入る語は？「'+blanked+'」',c,a]);cloze++;}
 VQCACHE.set(key,qs);return qs.map(q=>[q[0],q[1].slice(),q[2]]);
}
function vShortQuiz(it){
 spStop();clearTimeout(vAutoNext);it.quizOpen=true;const ov=it.el.querySelector('.endov');const qs=vShortQs(it.s);let k=0,ok=0,answered=false;
 const tail='<div class="row"><button class="btn sm" data-vq-again>もう一度見る</button><button class="btn sm" data-vq-detail>詳しく学ぶ →</button><button class="btn primary sm" data-vq-next>次の動画へ ↓</button></div>';
 const wire=()=>{ov.querySelector('[data-vq-again]').onclick=()=>{it.quizOpen=false;spPlay(it,0);};ov.querySelector('[data-vq-detail]').onclick=()=>vShortDetail(it);ov.querySelector('[data-vq-next]').onclick=()=>vShortNext(it);};
 const draw=()=>{
  if(!qs.length){ov.innerHTML='<p>この動画からは設問を作れませんでした。</p>'+tail;wire();return;}
  if(k>=qs.length){ov.innerHTML='<div style="font-size:17px;font-weight:700">設問 完了 · '+ok+' / '+qs.length+' 問正解</div><p class="small" style="opacity:.8">間違えた設問はマイページの復習リストに残ります。</p>'+tail;wire();return;}
  const q=qs[k];answered=false;
  ov.innerHTML='<div class="small" style="opacity:.8">設問 '+(k+1)+' / '+qs.length+' · '+esc(it.s.t)+'</div><div style="font-size:17px;font-weight:700">'+esc(q[0])+'</div><div class="choices">'+q[1].map((c,j)=>'<button data-vsq="'+j+'">'+esc(c)+'</button>').join('')+'</div><div data-vsqf></div>'+tail;wire();
  ov.querySelectorAll('[data-vsq]').forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const j=+b.dataset.vsq,right=j===q[2];if(right)ok++;
   ov.querySelectorAll('[data-vsq]').forEach(x=>{if(+x.dataset.vsq===q[2])x.classList.add('right');else if(x===b)x.classList.add('wrong');});
   videoMistake((it.s.id||'short')+'-sq'+k,q[0],q[1][q[2]],it.s.videoId||it.s.id,'ショートの設問',right);bump({compTot:1,compOk:right?1:0});
   const f=ov.querySelector('[data-vsqf]');f.innerHTML='<div class="fb '+(right?'ok':'ng')+'">'+(right?'正解':'正解は「'+esc(q[1][q[2]])+'」')+'</div>'+vExplanation(it.s,k)+'<button class="btn primary sm" data-vsq-go>'+(k+1<qs.length?'次の設問':'結果を見る')+'</button>';
   f.querySelector('[data-vsq-go]').onclick=()=>{k++;draw();};});
 };
 draw();ov.hidden=false;
}
