const oldRenderShortQ=renderShort;renderShort=function(it){const el=oldRenderShortQ(it);if(it&&it.type==='short'&&el&&el.querySelector){const h=el.querySelector('.shead'),n=vShortQs(it.s).length;if(h&&n){h.insertAdjacentHTML('beforeend','<button class="vqchip" data-vqchip aria-label="この動画の設問に答える">設問 '+n+'</button>');const b=h.querySelector('[data-vqchip]');if(b)b.onclick=e=>{e.stopPropagation();vShortQuiz(it);};}}return el;};
